effect.script:
function animate(env, el, p) {
var x = p.xinv ? -p.posx : p.posx;
var y = p.yinv ? -p.posy : p.posy;
var z = p.zinv ? 1 + (1 - p.posz) : p.posz;
var a = p.ainv ? -p.angle : p.angle;
el.transform.location.x += x;
el.transform.location.y += y;
el.transform.angle += a;
el.transform.scale.x += z - 1;
el.transform.scale.y += z - 1;
return el;
}

pass.shader:
uniform sampler2D inputImg;
uniform bool tileEnable;
uniform float tileStrength;
uniform float tileAmount;
uniform float tileSeed;
varying vec2 uv;
float rand(vec2 co) {
float a = 719.31;
float b = 178.233;
float c = 33758.5453;
float dt = dot(co.xy, vec2(a, b));
float sn = mod(dt, 3.14);
return fract(sin(sn) * c);
}
void main() {
vec2 uv_out = uv;
if (tileEnable) {
vec2 st = uv - 0.5;
float px = floor(st.x * tileAmount);
float py = floor(st.y * tileAmount);
float dx = rand(vec2(px, py + 3937.7249 * tileSeed));
float dy = rand(vec2(px + 328.7319 + 432.7249 * tileSeed, py - 971.382));
vec2 dv = (vec2(dx, dy) - 0.5) * 2.0;
uv_out += dv * tileStrength;
uv_out = abs(mod(uv_out - 1.0, 2.0) - 1.0);
}
gl_FragColor = texture2D(inputImg, uv_out);
}

uniform sampler2D inputImg;
uniform float motionBlurAmount;
varying vec2 uv;
void main() {
vec4 color = vec4(0.0);
float samples = 5.0;
float blurSize = motionBlurAmount * 0.02;
for (float i = 0.0; i < samples; i++) {
float offset = (i - 2.0) * blurSize;
color += texture2D(inputImg, uv + vec2(offset, 0.0));
}
gl_FragColor = color / samples;
}
